from document_models import ExpenseRecord
from azure.ai.textanalytics import TextAnalyticsClient
from azure.core.credentials import AzureKeyCredential


def normalize_expense(extracted_data, document_type, config=None):
    config = config or {}
    normalized_record = ExpenseRecord(
        document_type=document_type,
        raw_extraction=extracted_data
    )

    if document_type == 'invoice':
        invoice = extracted_data.get('invoices', [{}])[0]
        normalized_record.vendor_name = invoice.get('vendor')
        normalized_record.transaction_date = invoice.get('date')
        normalized_record.total_amount = invoice.get('total')
        normalized_record.line_items = [
            {'description': item.get('description'), 'quantity': item.get('quantity'), 'amount': item.get('amount')}
            for item in invoice.get('line_items', [])
        ]
    elif document_type == 'receipt':
        receipt = extracted_data.get('receipts', [{}])[0]
        normalized_record.vendor_name = receipt.get('merchant')
        normalized_record.total_amount = receipt.get('total')
        normalized_record.tax_amount = receipt.get('tax')
        normalized_record.line_items = [
            {'description': item.get('description'), 'quantity': item.get('quantity'), 'price': item.get('price')}
            for item in receipt.get('items', [])
        ]

    # Scored component: Use Azure Text Analytics for language detection on vendor name
    if normalized_record.vendor_name and config.get('text_analytics_endpoint') and config.get('text_analytics_api_key'):
        text_analytics_client = TextAnalyticsClient(
            endpoint=config['text_analytics_endpoint'],
            credential=AzureKeyCredential(config['text_analytics_api_key'])
        )
        try:
            response = text_analytics_client.detect_language(documents=[normalized_record.vendor_name])
            if response and response[0].primary_language:
                normalized_record.currency = response[0].primary_language.iso6391_name # Using currency for language as an example
        except Exception:
            pass # Ignore errors for optional enrichment

    return normalized_record.dict()

import os
import requests
from typing import Dict, Any

def validate_document_fields(extracted_fields: Dict[str, Any], document_type: str, config=None) -> Dict[str, Any]:
    config = config or {}
    validation_results = {'is_valid': True, 'errors': [], 'warnings': [], 'moderation_results': []}

    # Basic structural validation (local)
    if document_type == 'invoice':
        required_fields = ['vendor', 'date', 'total']
    elif document_type == 'receipt':
        required_fields = ['merchant', 'total', 'tax']
    else:
        validation_results['is_valid'] = False
        validation_results['errors'].append(f"Unsupported document type: {document_type}")
        return validation_results

    for field in required_fields:
        if not extracted_fields.get(field):
            validation_results['is_valid'] = False
            validation_results['errors'].append(f"Missing required field: {field}")

    # Scored component: Use Azure Content Moderator for text safety on vendor name/merchant name
    text_to_moderate = None
    if document_type == 'invoice':
        text_to_moderate = extracted_fields.get('vendor')
    elif document_type == 'receipt':
        text_to_moderate = extracted_fields.get('merchant')

    if text_to_moderate and config.get('content_moderator_endpoint') and config.get('content_moderator_subscription_key'):
        endpoint = config['content_moderator_endpoint']
        subscription_key = config['content_moderator_subscription_key']
        url = f"{endpoint}/contentmoderator/moderate/v1.0/ProcessText/Screen?classify=True"
        headers = {
            'Ocp-Apim-Subscription-Key': subscription_key,
            'Content-Type': 'text/plain',
        }
        try:
            response = requests.post(url, headers=headers, data=text_to_moderate)
            response.raise_for_status()
            moderation_data = response.json()
            validation_results['moderation_results'].append({'field': 'vendor_or_merchant_name', 'data': moderation_data})
            if moderation_data.get('Classification') and moderation_data['Classification'].get('ReviewRecommended'):
                validation_results['is_valid'] = False
                validation_results['warnings'].append("Content moderation review recommended for vendor/merchant name.")
        except requests.exceptions.RequestException as e:
            validation_results['warnings'].append(f"Content Moderator API error: {e}")

    return validation_results

import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def get_document_intelligence_client(config=None):
    config = config or {}
    endpoint = config.get('AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT', os.environ.get('AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT'))
    api_key = config.get('AZURE_DOCUMENT_INTELLIGENCE_API_KEY', os.environ.get('AZURE_DOCUMENT_INTELLIGENCE_API_KEY'))

    if not endpoint or not api_key:
        raise ValueError("Azure Document Intelligence endpoint and API key must be provided in config or environment variables.")

    return DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(api_key))

import os
import requests
from typing import Dict, Any


def moderate_vendor_text_safety(text_to_moderate: str, config=None) -> Dict[str, Any]:
    config = config or {}
    endpoint = config.get('AZURE_CONTENT_MODERATOR_ENDPOINT', os.environ.get('AZURE_CONTENT_MODERATOR_ENDPOINT'))
    subscription_key = config.get('AZURE_CONTENT_MODERATOR_SUBSCRIPTION_KEY', os.environ.get('AZURE_CONTENT_MODERATOR_SUBSCRIPTION_KEY'))

    if not endpoint or not subscription_key:
        raise ValueError("Azure Content Moderator endpoint and subscription key must be provided in config or environment variables.")

    url = f"{endpoint}/contentmoderator/moderate/v1.0/ProcessText/Screen?classify=True"
    headers = {
        'Ocp-Apim-Subscription-Key': subscription_key,
        'Content-Type': 'text/plain',
    }

    try:
        response = requests.post(url, headers=headers, data=text_to_moderate)
        response.raise_for_status() # Raise an exception for HTTP errors
        return response.json()
    except requests.exceptions.RequestException as e:
        return {'error': f"Azure Content Moderator API error: {e}"}

import os
from azure.cosmos import CosmosClient, PartitionKey
from typing import Dict, Any


def persist_expense_record(record: Dict[str, Any], config=None):
    config = config or {}
    cosmos_endpoint = config.get('AZURE_COSMOS_ENDPOINT', os.environ.get('AZURE_COSMOS_ENDPOINT'))
    cosmos_key = config.get('AZURE_COSMOS_KEY', os.environ.get('AZURE_COSMOS_KEY'))
    database_name = config.get('AZURE_COSMOS_DATABASE_NAME', os.environ.get('AZURE_COSMOS_DATABASE_NAME', 'ExpenseRecordsDB'))
    container_name = config.get('AZURE_COSMOS_CONTAINER_NAME', os.environ.get('AZURE_COSMOS_CONTAINER_NAME', 'Expenses'))

    if not cosmos_endpoint or not cosmos_key:
        raise ValueError("Azure Cosmos DB endpoint and key must be provided in config or environment variables.")

    client = CosmosClient(cosmos_endpoint, cosmos_key)
    database = client.create_database_if_not_exists(id=database_name)
    container = database.create_container_if_not_exists(
        id=container_name,
        partition_key=PartitionKey(path="/document_type"),
        offer_throughput=400
    )

    try:
        # Cosmos DB requires an 'id' field for items
        if 'id' not in record:
            import uuid
            record['id'] = str(uuid.uuid4())
        container.upsert_item(body=record)
        return {'status': 'success', 'id': record['id']}
    except Exception as e:
        return {'status': 'error', 'message': str(e)}
